compile.workshop:
variables {
    player:
        0: I
}

rule ("player range") {
    event {
        Ongoing - Global;
    }
    actions {
        For Player Variable(Host Player, I, 0, 3, 1);
            Set Player Variable(Host Player, I, 1);
        End;
    }
}

